import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './index.css';

function App() {
  const [user, setUser] = useState(null);
  const [page, setPage] = useState('login');
  const [emailInput, setEmailInput] = useState('');
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [formData, setFormData] = useState({});
  const [courses, setCourses] = useState([]);
  const [enrolledCourseIds, setEnrolledCourseIds] = useState([]);

  // New: For assignment submission (student)
  const [selectedAssignment, setSelectedAssignment] = useState(null);
  const [submissionFileUrl, setSubmissionFileUrl] = useState('');

  // Modals
  const [showConfirmDelete, setShowConfirmDelete] = useState(false);
  const [itemToDelete, setItemToDelete] = useState(null);
  const [deleteBase, setDeleteBase] = useState('');
  const [showStudentsModal, setShowStudentsModal] = useState(false);
  const [selectedCourseStudents, setSelectedCourseStudents] = useState([]);

  const API = 'http://localhost:5000/api';

  const getEndpoint = (pageName) => {
    if (pageName === 'courses') return 'courses';
    if (pageName === 'assignments') return 'assignments';
    if (pageName === 'announcements') return 'announcements';
    if (pageName === 'submissions') {
      return user?.role === 'student' ? `submissions?studentid=${user.id}` : 'submissions';
    }
    if (pageName === 'students') return 'users?role=student';
    return null;
  };

  const getEmptyForm = (pageName) => {
    if (pageName === 'courses') return { title: '', description: '', syllabus: '' };
    if (pageName === 'assignments') return { title: '', duedate: '', description: '', courseid: '' };
    if (pageName === 'announcements') return { title: '', message: '', courseid: '' };
    if (pageName === 'students') return { name: '', email: '' };
    return {};
  };

  const login = async (e) => {
    e.preventDefault();
    if (!emailInput.trim()) return alert('Please enter your email');
    try {
      const res = await axios.post(`${API}/users/login`, { email: emailInput.trim() });
      setUser(res.data);
      setPage('courses');
    } catch (err) {
      alert('Login failed — user not found');
    }
  };

  const logout = () => {
    setUser(null);
    setPage('login');
    setEmailInput('');
    setData([]);
    setCourses([]);
    setEnrolledCourseIds([]);
    setSelectedAssignment(null);
    setSubmissionFileUrl('');
  };

  const load = async (endpoint) => {
    if (!endpoint) return [];
    setLoading(true);
    try {
      const res = await axios.get(`${API}/${endpoint}`);
      let fetched = res.data;

      if (endpoint.includes('courses')) {
        fetched = fetched.map(course => ({
          ...course,
          students: Array.isArray(course.students) ? course.students.map(Number) : []
        }));
        setCourses(fetched);
      }

      setData(fetched);
      return fetched;
    } catch (err) {
      console.error(err);
      setData([]);
      return [];
    } finally {
      setLoading(false);
    }
  };

  const goTo = async (newPage) => {
    setPage(newPage);
    setShowForm(false);
    setEditingItem(null);
    setFormData({});
    setSelectedAssignment(null);
    setSubmissionFileUrl('');

    const endpoint = getEndpoint(newPage);
    if (endpoint) {
      let fetched = await load(endpoint);

      // Filter for students
      if (newPage === 'assignments' && user?.role === 'student') {
        const studentAssignments = fetched.filter(a => enrolledCourseIds.includes(a.courseid));
        setData(studentAssignments);
      }
      if (newPage === 'announcements' && user?.role === 'student') {
        const studentAnnouncements = fetched.filter(a => enrolledCourseIds.includes(a.courseid));
        setData(studentAnnouncements);
      }
    }
  };

  useEffect(() => {
    if (user) {
      load('courses').then(fetchedCourses => {
        const enrolledIds = fetchedCourses
          .filter(c => (c.students || []).includes(user.id))
          .map(c => c.id);
        setEnrolledCourseIds(enrolledIds);
      });

      if (page !== 'login') goTo(page);
    }
  }, [user]);

  const enroll = async (courseId) => {
    try {
      const res = await axios.post(`${API}/courses/${courseId}/enroll`, { studentid: user.id });
      const updatedStudents = res.data.students ? res.data.students.map(Number) : [];
      setData(prev => prev.map(c => c.id === courseId ? { ...c, students: updatedStudents } : c));
      setEnrolledCourseIds(prev => [...prev, courseId]);
      alert('Enrolled successfully!');
    } catch (err) {
      alert('Already enrolled or error');
    }
  };

  const drop = async (courseId) => {
    try {
      const res = await axios.post(`${API}/courses/${courseId}/drop`, { studentid: user.id });
      const updatedStudents = res.data.students ? res.data.students.map(Number) : [];
      setData(prev => prev.map(c => c.id === courseId ? { ...c, students: updatedStudents } : c));
      setEnrolledCourseIds(prev => prev.filter(id => id !== courseId));
      alert('Dropped successfully!');
    } catch (err) {
      alert('Error dropping course');
    }
  };

  // New: Student submits assignment
  const submitAssignment = async (assignmentId) => {
    if (!submissionFileUrl.trim()) {
      alert('Please enter a file URL (e.g., Google Drive link)');
      return;
    }
    try {
      await axios.post(`${API}/submissions`, {
        assignmentid: assignmentId,
        studentid: user.id,
        fileurl: submissionFileUrl
      });
      alert('Assignment submitted successfully!');
      setSubmissionFileUrl('');
      setSelectedAssignment(null);
    } catch (err) {
      alert('Submission failed: ' + (err.response?.data?.error || 'Unknown error'));
    }
  };

  const startAdd = () => {
    setEditingItem(null);
    setFormData(getEmptyForm(page));
    setShowForm(true);
  };

  const startEdit = (item) => {
    setEditingItem(item);
    setFormData({ ...item });
    setShowForm(true);
  };

  const openDeleteConfirm = (id, base) => {
    setItemToDelete(id);
    setDeleteBase(base);
    setShowConfirmDelete(true);
  };

  const confirmDelete = async () => {
    try {
      await axios.delete(`${API}/${deleteBase}/${itemToDelete}`);
      alert('Deleted successfully');
      setShowConfirmDelete(false);
      await goTo(page);
    } catch (err) {
      alert('Delete failed');
    }
  };

  const saveItem = async (e) => {
    e.preventDefault();
    const base = page === 'students' ? 'users' : page;
    let payload = { ...formData };

    if (page === 'courses') payload.instructorid = user.id;
    if (page === 'students') payload.role = 'student';

    if ((page === 'announcements' || page === 'assignments') && !payload.courseid) {
      alert('Please select a valid course.');
      return;
    }

    try {
      if (editingItem) {
        await axios.put(`${API}/${base}/${editingItem.id}`, payload);
        alert('Updated!');
      } else {
        await axios.post(`${API}/${base}`, payload);
        alert('Created!');
      }
      setShowForm(false);
      await goTo(page);
    } catch (err) {
      alert('Error: ' + (err.response?.data?.error || 'Invalid data'));
    }
  };

  const viewEnrolledStudents = (course) => {
    const students = (course.students || []).map(id => ({
      id,
      name: `Student ${id}`,
      email: `student${id}@example.com`
    }));
    setSelectedCourseStudents(students);
    setShowStudentsModal(true);
  };

  return (
    <div className="app">
      {page === 'login' && !user && (
        <div className="container">
          <h1>NM Student Portal</h1>
          <form onSubmit={login}>
            <input
              type="email"
              placeholder="Enter your email"
              value={emailInput}
              onChange={(e) => setEmailInput(e.target.value)}
              required
              style={{ width: '100%', padding: '10px', margin: '10px 0' }}
            />
            <button type="submit" className="btn">Login</button>
          </form>
        </div>
      )}

      {user && (
        <>
          <nav>
            <button onClick={() => goTo('courses')} className="btn">Courses</button>
            {user.role === 'student' && (
              <>
                <button onClick={() => goTo('assignments')} className="btn">Assignments</button>
                <button onClick={() => goTo('announcements')} className="btn">Announcements</button>
                <button onClick={() => goTo('submissions')} className="btn">My Submissions</button>
              </>
            )}
            {user.role === 'instructor' && (
              <>
                <button onClick={() => goTo('assignments')} className="btn">Assignments</button>
                <button onClick={() => goTo('announcements')} className="btn">Announcements</button>
                <button onClick={() => goTo('students')} className="btn">Students</button>
              </>
            )}
            <button onClick={logout} className="btn" style={{ background: '#e74c3c' }}>Logout</button>
          </nav>

          <div className="container">
            <h1>Welcome, {user.name} ({user.role})</h1>
            <h2>{page.charAt(0).toUpperCase() + page.slice(1)}</h2>

            {user.role === 'instructor' && ['courses', 'assignments', 'announcements', 'students'].includes(page) && (
              <button onClick={startAdd} className="btn">+ Add New</button>
            )}

            {loading && <p>Loading...</p>}

            {data.length > 0 && (
              <table>
                <thead>
                  <tr>
                    <th>ID</th>
                    {page === 'courses' && <th>Title</th>}
                    {page === 'courses' && <th>Description</th>}
                    {page === 'courses' && <th>Syllabus</th>}
                    {page === 'courses' && user.role === 'instructor' && <th>Enrolled</th>}
                    {page === 'courses' && <th>Action</th>}

                    {(page === 'assignments' || page === 'announcements') && <th>Title</th>}
                    {page === 'assignments' && <th>Due Date</th>}
                    {page === 'assignments' && <th>Description</th>}
                    {(page === 'assignments' || page === 'announcements') && <th>Course ID</th>}
                    {(page === 'assignments' || page === 'announcements') && user.role === 'instructor' && <th>Actions</th>}

                    {page === 'submissions' && <th>Assignment ID</th>}
                    {page === 'submissions' && <th>Student ID</th>}
                    {page === 'submissions' && <th>File</th>}
                    {page === 'submissions' && <th>Grade</th>}

                    {page === 'students' && <th>Name</th>}
                    {page === 'students' && <th>Email</th>}
                    {page === 'students' && <th>Actions</th>}
                  </tr>
                </thead>
                <tbody>
                  {data.map(item => (
                    <tr key={item.id}>
                      <td>{item.id}</td>

                      {page === 'courses' && <td>{item.title}</td>}
                      {page === 'courses' && <td>{item.description}</td>}
                      {page === 'courses' && <td>{item.syllabus || '—'}</td>}
                      {page === 'courses' && user.role === 'instructor' && (
                        <td>
                          <button onClick={() => viewEnrolledStudents(item)} className="btn">
                            View ({(item.students || []).length})
                          </button>
                        </td>
                      )}
                      {page === 'courses' && (
                        <td>
                          {user.role === 'instructor' && (
                            <>
                              <button onClick={() => startEdit(item)} className="btn">Edit</button>
                              <button onClick={() => openDeleteConfirm(item.id, 'courses')} className="btn" style={{ background: '#e74c3c' }}>Delete</button>
                            </>
                          )}
                          {user.role === 'student' && (
                            <button
                              onClick={() => (item.students || []).includes(user.id) ? drop(item.id) : enroll(item.id)}
                              className="btn"
                              style={{ background: (item.students || []).includes(user.id) ? '#e67e22' : '#4facfe' }}
                            >
                              {(item.students || []).includes(user.id) ? 'Drop' : 'Enroll'}
                            </button>
                          )}
                        </td>
                      )}

                      {(page === 'assignments' || page === 'announcements') && <td>{item.title}</td>}
                      {page === 'assignments' && <td>{item.duedate || 'No due date'}</td>}
                      {page === 'assignments' && <td>{item.description || '—'}</td>}
                      {(page === 'assignments' || page === 'announcements') && <td>{item.courseid}</td>}
                      {(page === 'assignments' || page === 'announcements') && user.role === 'instructor' && (
                        <td>
                          <button onClick={() => startEdit(item)} className="btn">Edit</button>
                          <button onClick={() => openDeleteConfirm(item.id, page === 'assignments' ? 'assignments' : 'announcements')} className="btn" style={{ background: '#e74c3c' }}>Delete</button>
                        </td>
                      )}

                      {page === 'assignments' && user.role === 'student' && (
                        <td>
                          <button
                            onClick={() => setSelectedAssignment(item)}
                            className="btn"
                            style={{ background: '#4facfe' }}
                          >
                            Submit
                          </button>
                        </td>
                      )}

                      {page === 'submissions' && <td>{item.assignmentid}</td>}
                      {page === 'submissions' && <td>{item.studentid}</td>}
                      {page === 'submissions' && <td>{item.fileurl ? <a href={item.fileurl} target="_blank" rel="noreferrer">View File</a> : 'No file'}</td>}
                      {page === 'submissions' && <td>{item.grade !== null ? `${item.grade}/100` : 'Not graded'}</td>}

                      {page === 'students' && <td>{item.name}</td>}
                      {page === 'students' && <td>{item.email}</td>}
                      {page === 'students' && (
                        <td>
                          <button onClick={() => startEdit(item)} className="btn">Edit</button>
                          <button onClick={() => openDeleteConfirm(item.id, 'users')} className="btn" style={{ background: '#e74c3c' }}>Delete</button>
                        </td>
                      )}
                    </tr>
                  ))}
                </tbody>
              </table>
            )}

            {/* Assignment Submission Modal (Student) */}
            {selectedAssignment && user.role === 'student' && (
              <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <div style={{ background: 'white', color: '#333', padding: '30px', borderRadius: '10px', width: '500px' }}>
                  <h3>Submit Assignment: {selectedAssignment.title}</h3>
                  <p><strong>Due:</strong> {selectedAssignment.duedate || 'No due date'}</p>
                  <p><strong>Description:</strong> {selectedAssignment.description || '—'}</p>
                  <label>File URL (e.g., Google Drive link):</label>
                  <input
                    type="text"
                    value={submissionFileUrl}
                    onChange={(e) => setSubmissionFileUrl(e.target.value)}
                    placeholder="https://drive.google.com/..."
                    style={{ width: '100%', padding: '10px', margin: '10px 0' }}
                    required
                  />
                  <button onClick={() => submitAssignment(selectedAssignment.id)} className="btn">Submit Assignment</button>
                  <button onClick={() => { setSelectedAssignment(null); setSubmissionFileUrl(''); }} className="btn" style={{ background: '#e74c3c', marginLeft: '10px' }}>Cancel</button>
                </div>
              </div>
            )}

            {/* Form Modal (Add/Edit) */}
            {showForm && (
              <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <div style={{ background: 'white', color: '#333', padding: '30px', borderRadius: '10px', width: '500px' }}>
                  <h3>{editingItem ? 'Edit' : 'Add'} {page.slice(0, -1)}</h3>
                  <form onSubmit={saveItem}>
                    {Object.keys(getEmptyForm(page)).map(key => (
                      <div key={key} style={{ marginBottom: '15px' }}>
                        <label>{key.charAt(0).toUpperCase() + key.slice(1)}:</label>
                        {['announcements', 'assignments'].includes(page) && key === 'courseid' ? (
                          <select
                            value={formData[key] || ''}
                            onChange={(e) => setFormData({ ...formData, [key]: e.target.value })}
                            required
                            style={{ width: '100%', padding: '10px', marginTop: '5px' }}
                          >
                            <option value="">Select a course</option>
                            {courses.map(course => (
                              <option key={course.id} value={course.id}>
                                {course.id} - {course.title}
                              </option>
                            ))}
                          </select>
                        ) : (
                          <input
                            type={key === 'duedate' ? 'date' : 'text'}
                            value={formData[key] || ''}
                            onChange={(e) => setFormData({ ...formData, [key]: e.target.value })}
                            style={{ width: '100%', padding: '10px', marginTop: '5px' }}
                            required
                          />
                        )}
                      </div>
                    ))}
                    <button type="submit" className="btn">Save</button>
                    <button type="button" onClick={() => setShowForm(false)} className="btn" style={{ background: '#e74c3c', marginLeft: '10px' }}>Cancel</button>
                  </form>
                </div>
              </div>
            )}

            {/* Delete Confirmation */}
            {showConfirmDelete && (
              <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <div style={{ background: 'white', padding: '30px', borderRadius: '10px', textAlign: 'center' }}>
                  <h3>Confirm Delete</h3>
                  <p>Are you sure you want to delete this permanently?</p>
                  <button onClick={confirmDelete} className="btn" style={{ background: '#e74c3c' }}>Yes, Delete</button>
                  <button onClick={() => setShowConfirmDelete(false)} className="btn" style={{ marginLeft: '10px' }}>Cancel</button>
                </div>
              </div>
            )}

            {/* Enrolled Students Modal */}
            {showStudentsModal && (
              <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <div style={{ background: 'white', padding: '30px', borderRadius: '10px', maxWidth: '500px' }}>
                  <h3>Enrolled Students</h3>
                  {selectedCourseStudents.length > 0 ? (
                    <ul style={{ listStyle: 'none', padding: 0 }}>
                      {selectedCourseStudents.map(s => (
                        <li key={s.id} style={{ padding: '8px 0', borderBottom: '1px solid #ddd' }}>
                          {s.name} ({s.email})
                        </li>
                      ))}
                    </ul>
                  ) : <p>No students enrolled.</p>}
                  <button onClick={() => setShowStudentsModal(false)} className="btn">Close</button>
                </div>
              </div>
            )}
          </div>
        </>
      )}

      <footer>
        <h3>NM Student Portal © 2025</h3>
        <p>Full Role-Based System • All Features Working</p>
      </footer>
    </div>
  );
}

export default App;
